module.exports = function(RED) {
    "use strict";

    const {createHash, timingSafeEqual} = require("crypto");

    function hasValidToken(header, rawHeaders, expectedToken) {
        if (typeof header !== "string" || !Array.isArray(rawHeaders) && rawHeaders !== undefined) {
            return false;
        }
        if (rawHeaders) {
            let authorizationHeaders = 0;
            for (let index = 0; index < rawHeaders.length; index += 2) {
                if (typeof rawHeaders[index] === "string" && rawHeaders[index].toLowerCase() === "authorization") {
                    authorizationHeaders++;
                }
            }
            if (authorizationHeaders !== 1) {
                return false;
            }
        }
        const match = /^Bearer[ \t]+([^\s]+)$/i.exec(header.trim());
        if (!match) {
            return false;
        }
        const expected = createHash("sha256").update(expectedToken).digest();
        const supplied = createHash("sha256").update(match[1]).digest();
        return timingSafeEqual(expected, supplied);
    }

    function BearerAuthNode(config) {
        RED.nodes.createNode(this, config);
        const node = this;

        node.on("input", function(msg, send, done) {
            const response = msg.res && msg.res._res;
            if (!response || typeof response.status !== "function" || typeof response.set !== "function" ||
                    typeof response.send !== "function" || response.headersSent) {
                done(new Error("Bearer auth requires an unanswered HTTP In request"));
                return;
            }
            const token = node.credentials && node.credentials.token;
            if (typeof token !== "string" || !token) {
                node.status({fill: "red", shape: "ring", text: "token not configured"});
                response.set("Cache-Control", "no-store").status(503).send("Service Unavailable");
                done();
                return;
            }

            const request = msg.req;
            const header = request && request.headers && request.headers.authorization;
            const rawHeaders = request && (request.rawHeaders || (request._req && request._req.rawHeaders));
            if (!hasValidToken(header, rawHeaders, token)) {
                response.set("WWW-Authenticate", "Bearer").set("Cache-Control", "no-store").status(401).send("Unauthorized");
                done();
                return;
            }

            node.status({});
            send(msg);
            done();
        });
    }

    RED.nodes.registerType("bearer auth", BearerAuthNode, {
        credentials: {
            token: {type: "password"}
        }
    });
};
